// Ijabo minimal helpers
window.ijabo = {
    showToast: function(message, type) {
        var cls = type || 'info';
        var toast = $('<div class="ijabo-toast ' + cls + '">' + message + '</div>');
        $('body').append(toast);
        setTimeout(function(){ toast.addClass('show'); }, 100);
        setTimeout(function(){ 
            toast.removeClass('show'); 
            setTimeout(function(){ toast.remove(); }, 300);
        }, 3000);
    }
};
